// One design's page (/designs/<slug>/, generated by make-design-pages.mjs from the canvas Design.dc.html).
// Adds: the picture views (Opening is the real still; Invitation, Ceremonies and RSVP are drawn), the colour and
// language controls on the drawn views, the info tabs, the live price, communities and contact, related designs the
// admin has not hidden, and the watermarked preview. Never links the clean theme page.
import './site.css';
import './design.css';
import { $, $$, el, SLUG_RE, initPreview, applyContact, setYear } from './common.js';
import { loadSite, loadThemes } from './api.js';
import { BY_SLUG, CATEGORIES, RELIGION_LABEL } from './themes.js';
import SMALL_THUMBS from './thumbs.json';
import STILLS from './stills.json';
import { phoneStill, STILL_SIZES } from './stills.js';

const slug = document.body.dataset.slug;
const small = new Set(SMALL_THUMBS);
const CAPS = [$('#g-cap')?.textContent || 'The design', 'The invitation', 'Every ceremony', 'RSVP']; // the first is per design (the still)

/** a radio group or tab list with roving focus: arrows, Home and End move; `pick(i)` applies the choice */
function roving(group, role, pick) {
  const items = $$(`[role="${role}"]`, group);
  const attr = role === 'tab' ? 'aria-selected' : 'aria-checked';
  const select = (i, focus = false) => {
    items.forEach((b, k) => { b.setAttribute(attr, String(k === i)); b.tabIndex = k === i ? 0 : -1; });
    pick(i, items[i]);
    if (focus) items[i].focus();
  };
  group.addEventListener('click', (e) => { const b = e.target.closest(`[role="${role}"]`); if (b) select(items.indexOf(b)); });
  group.addEventListener('keydown', (e) => {
    const i = items.indexOf(document.activeElement);
    if (i < 0) return;
    const n = items.length;
    const to = { ArrowRight: (i + 1) % n, ArrowDown: (i + 1) % n, ArrowLeft: (i - 1 + n) % n, ArrowUp: (i - 1 + n) % n, Home: 0, End: n - 1 }[e.key];
    if (to == null) return;
    e.preventDefault();
    select(to, true);
  });
}

function initGallery() {
  const g = $('#gallery');
  const screens = $$('.gscreen', g);
  roving($('.gallery__views', g), 'tab', (i) => {
    screens.forEach((s) => { s.hidden = Number(s.dataset.view) !== i; });
    $('#g-cap').textContent = CAPS[i];
    $('#g-main').setAttribute('aria-labelledby', `g-tab-${i}`);
  });
  roving($('#d-swatches'), 'radio', (i, b) => {
    for (const k of ['a', 'b', 'bg', 'tint']) g.style.setProperty(`--${k}`, b.dataset[k]);
    $('#d-theme-name').textContent = b.dataset.name;
  });
  roving($('#d-langs'), 'radio', (i, b) => {
    const ne = b.dataset.lang === 'ne';
    for (const n of $$('[data-en]', g)) {
      n.textContent = ne ? n.dataset.ne : n.dataset.en;
      if (ne) n.setAttribute('lang', 'ne'); else n.removeAttribute('lang');
    }
    // show the drawn invitation, where the language is visible
    if ($('#g-tab-1').getAttribute('aria-selected') !== 'true') $('#g-tab-1').click();
  });
}

const phonePic = (t) => phoneStill(STILLS, t.slug, small.has(t.slug) ? `/site/thumbs/${t.slug}-480.webp` : t.thumb);
const relatedCard = (t, from) => el('li', {},
  el('a', { class: 'rcard', href: `/designs/${t.slug}/` },
    el('span', { class: 'rcard__pic', style: `--tint:${(CATEGORIES[t.cat] || CATEGORIES.cards).tint}` },
      el('span', { class: 'rcard__phone' }, el('img', { src: phonePic(t).src, srcset: phonePic(t).srcset || null, sizes: phonePic(t).srcset ? STILL_SIZES.related : null, width: 390, height: 844, alt: '', loading: 'lazy', decoding: 'async' }))),
    el('span', { class: 'rcard__name' }, document.createTextNode(`${t.name} `), t.ne ? el('span', { class: 'rcard__ne', lang: 'ne', text: t.ne }) : null),
    el('span', { class: 'rcard__meta' }, document.createTextNode(`${(CATEGORIES[t.cat]?.label || 'design').toLowerCase()} · `), el('span', { class: 'js-from', text: from }))));

const suitsText = (rel) => {
  const names = rel.filter((r) => r !== 'other').map((r) => RELIGION_LABEL[r]);
  if (rel.includes('other')) names.push('other');
  return `${names.length > 1 ? `${names.slice(0, -1).join(', ')} and ${names[names.length - 1]}` : names[0]} weddings`;
};

async function boot() {
  if (!SLUG_RE.test(slug || '')) return;
  setYear();
  initGallery();
  roving($('.tabs__list'), 'tab', (i) => { $$('.tabs__panel').forEach((p, k) => { p.hidden = k !== i; }); });
  let themes = [];
  initPreview({
    find: (s) => themes.find((t) => t.slug === s) || BY_SLUG[s],
    onOrder: (s) => location.assign(`/?design=${encodeURIComponent(s)}#order`),
  });

  const site = await loadSite();
  applyContact(site.contact);
  const prices = site.plans.filter((p) => p.price != null && !p.from).map((p) => p.price);
  const low = prices.length ? Math.min(...prices) : null;
  const from = low != null ? `from Rs. ${new Intl.NumberFormat('en-IN').format(low)}` : 'ask for price';
  $('#d-price').textContent = low != null ? from : 'Ask us for the price';
  for (const n of $$('.js-from')) n.textContent = from;

  themes = await loadThemes(site);
  for (const n of $$('.js-count')) n.textContent = String(themes.length);
  const me = themes.find((t) => t.slug === slug);
  if (!me) {
    // hidden by the admin (or gone): keep the page readable, but do not take orders for it
    $('#d-off').hidden = false;
    $('#d-order').hidden = true;
  } else if (me.religions?.length) {
    $('#d-suits').textContent = suitsText(me.religions);
  }
  // related: three designs the visitor can order, same group first
  const shown = $$('#related a').map((a) => a.getAttribute('href').split('/')[2]);
  const ok = new Set(themes.map((t) => t.slug));
  if (themes.length && shown.some((s) => !ok.has(s))) {
    const cat = me?.cat || BY_SLUG[slug]?.cat;
    const pool = themes.filter((t) => t.slug !== slug);
    const pick = [...pool.filter((t) => t.cat === cat), ...pool.filter((t) => t.cat !== cat)].slice(0, 3);
    $('#related').replaceChildren(...pick.map((t) => relatedCard(t, from)));
  }
}
boot();
